const inputClass =
  'h-11 rounded-xl border border-slate-300 bg-white px-3 text-sm outline-none focus:border-cyan-600 focus:ring-2 focus:ring-cyan-100'
import { ShiftSelect } from '@features/hr-shifts/ShiftSelect'
