function DepartureDialog({ vehicle, onClose }: { vehicle: GarageVehicle; onClose: () => void }) {
  const assignments = useGarageShiftAssignments(vehicle.id)
  const departure = useRecordGarageShiftDeparture()
  const canDepart = useCanCall('garage_record_shift_departure')
  const shiftOptions = useShiftOptions(false)
  const shiftName = useShiftLabel()
  const [shift, setShift] = useState<GarageShift>(vehicle.shift)
  const recipients = useGarageShiftDispatchRecipients(vehicle.id, shift)
  const [notes, setNotes] = useState('')
  const [mode, setMode] = useState<'auto' | 'manual'>('auto')
  const [manualId, setManualId] = useState('')
  // 00377: أساسي أو احتياطي في الشفت نفسه
  const [driverRole, setDriverRole] = useState<'primary' | 'backup'>('primary')
  const active = (assignments.data ?? []).filter((assignment) => !assignment.endsAt)
  const primaryOf = (code: string) => active.find((a) => a.shift === code && a.driverRole !== 'backup')
  const backupOf = (code: string) => active.find((a) => a.shift === code && a.driverRole === 'backup')
  const backup = backupOf(shift)
  const selected = driverRole === 'backup' && backup ? backup : primaryOf(shift)
  const candidates = recipients.data ?? []
  const automaticManager = candidates.find((candidate) => candidate.pickRank === 1) ?? null
  const manualChoice = candidates.find((candidate) => candidate.userId === manualId) ?? null
  const effectiveManager = mode === 'manual' ? manualChoice : automaticManager
  const submit = (event: React.FormEvent) => {
    event.preventDefault()
    if (!selected || !effectiveManager) return
    departure.mutate(
      {
        vehicleId: vehicle.id,
        shift,
        notes: notes || undefined,
        managerId: mode === 'manual' ? effectiveManager.userId : undefined,
        driverRole: driverRole === 'backup' && backup ? 'backup' : 'primary',
      },
      { onSuccess: onClose },
    )
  }
  return (
    <div
      className="fixed inset-0 z-[1800] flex items-center justify-center bg-slate-950/70 p-3 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      dir="rtl"
    >
      <form
        onSubmit={submit}
        className="w-full max-w-lg overflow-hidden rounded-3xl bg-white shadow-2xl"
      >
        <header className="bg-slate-950 p-6 text-white">
          <span className="text-[10px] font-black tracking-widest text-cyan-300">
            AUTOMATIC DISPATCH
          </span>
          <h2 className="mt-1 text-xl font-black">إطلاق الآلية إلى مسؤول منطقتها</h2>
          <p className="mt-1 text-xs text-slate-400">
            {vehicle.vehicleName} · DB {vehicle.dbNumber}
          </p>
        </header>
        <div className="p-6">
          <label className="block text-xs font-black">الشفت والسائق</label>
          <select
            aria-label="شفت انطلاق الآلية"
            value={shift}
            onChange={(event) => { setShift(event.target.value as GarageShift); setDriverRole('primary') }}
            className="mt-2 h-12 w-full rounded-xl border px-3"
          >
            {(shiftOptions.data ?? []).map((o) => o.code).map((value) => (
              <option key={value} value={value}>
                {shiftName(value)} —{' '}
                {primaryOf(value)?.driverName ?? 'لا يوجد إسناد'}
                {backupOf(value) ? ` (+ احتياطي: ${backupOf(value)?.driverName})` : ''}
              </option>
            ))}
          </select>
          {backup && (
            <div className="mt-2 grid grid-cols-2 gap-2" data-testid="dispatch-driver-role">
              {(['primary', 'backup'] as const).map((r) => {
                const a = r === 'backup' ? backup : primaryOf(shift)
                return (
                  <button key={r} type="button" data-testid={`dispatch-driver-role-${r}`} aria-pressed={driverRole === r}
                    onClick={() => setDriverRole(r)}
                    className={`rounded-xl px-3 py-2 text-right text-xs font-black ring-1 ${driverRole === r ? 'bg-slate-900 text-white ring-slate-900' : 'bg-white text-slate-700 ring-slate-300'}`}>
                    <span className="block text-[10px] opacity-70">{r === 'backup' ? 'السائق الاحتياطي' : 'السائق الأساسي'}</span>
                    {a?.driverName ?? '—'}
                  </button>
                )
              })}
            </div>
          )}
          {selected ? (
            <div className="mt-3 rounded-2xl border border-emerald-200 bg-emerald-50 p-4">
              <div className="flex items-center gap-3">
                <span className="grid size-9 place-items-center rounded-xl bg-emerald-600 text-white">
                  <MapPin size={17} />
                </span>
                <div>
                  <b className="block text-sm">{selected.areaName}</b>
                  <p className="text-[10px] text-emerald-800">
                    السائق: {selected.driverName}{selected.driverRole === 'backup' ? ' (احتياطي)' : ''}{selected.contractorName ? ` · متعهد: ${selected.contractorName}` : ''} · الشفت {shiftName(selected.shift)}
                  </p>
                </div>
              </div>
              <div className="mt-3 border-t border-emerald-200 pt-3 text-[11px] font-bold leading-5 text-emerald-900">
                {recipients.isLoading ? (
                  <span>جارٍ تحديد مسؤول المنطقة…</span>
                ) : automaticManager ? (
                  <>
                    <span className="block" data-testid="dispatch-manager-line">
                      {mode === 'manual' ? 'المسؤول المختار يدوياً:' : 'المسؤول المستلم تلقائياً:'}{' '}
                      {effectiveManager?.managerName ?? '—'}
                    </span>
                    {mode === 'auto' && automaticManager.resolution === 'parent_fallback' && (
                      <span
                        data-testid="dispatch-fallback-note"
                        className="mt-1 block font-normal text-amber-800"
                      >
                        لا مدير مباشر لهذه المنطقة — ارتد الإسناد تلقائياً إلى مسؤول يغطي قطاعاً
                        شقيقاً ضمن القاطع نفسه.
                      </span>
                    )}
                    {candidates.length > 1 && (
                      <span className="block font-normal text-slate-600">
                        يوجد {candidates.length} مسؤولين متوافقين؛ الإسناد التلقائي للأكثر تحديداً
                        ويمكنك الاختيار يدوياً.
                      </span>
                    )}
                    <div className="mt-2 grid grid-cols-2 gap-2">
                      <button
                        type="button"
                        data-testid="dispatch-mode-auto"
                        onClick={() => setMode('auto')}
                        className={`h-9 rounded-xl text-[11px] font-black transition ${mode === 'auto' ? 'bg-emerald-600 text-white' : 'border bg-white text-slate-600'}`}
                      >
                        إسناد تلقائي
                      </button>
                      <button
                        type="button"
                        data-testid="dispatch-mode-manual"
                        onClick={() => setMode('manual')}
                        className={`h-9 rounded-xl text-[11px] font-black transition ${mode === 'manual' ? 'bg-emerald-600 text-white' : 'border bg-white text-slate-600'}`}
                      >
                        اختيار يدوي
                      </button>
                    </div>
                    {mode === 'manual' && (
                      <select
                        aria-label="اختيار المسؤول يدوياً"
                        data-testid="manual-manager-select"
                        value={manualId}
                        onChange={(event) => setManualId(event.target.value)}
                        className="mt-2 h-11 w-full rounded-xl border bg-white px-3 text-sm"
                      >
                        <option value="">— اختر المسؤول —</option>
                        {candidates.map((candidate) => (
                          <option key={candidate.userId} value={candidate.userId}>
                            {candidate.managerName} ·{' '}
                            {candidate.resolution === 'direct' ? 'تغطية مباشرة' : 'ضمن القاطع'} ·
                            شفت {shiftName(candidate.shift)}
                          </option>
                        ))}
                      </select>
                    )}
                  </>
                ) : (
                  <span className="text-rose-700">
                    لم يُهيأ مسؤول لهذه المنطقة ولا لأي منطقة ضمن قاطعها بعد.
                  </span>
                )}
              </div>
            </div>
          ) : (
            <p className="mt-3 rounded-xl bg-rose-50 p-3 text-xs font-bold text-rose-700">
              لا يوجد سائق ومنطقة مسندان لهذا الشفت. أكمل الإسناد أولاً.
            </p>
          )}
          <textarea
            aria-label="ملاحظات الانطلاق"
            value={notes}
            onChange={(event) => setNotes(event.target.value)}
            maxLength={500}
            rows={3}
            className="mt-4 w-full rounded-xl border p-3 text-sm"
            placeholder="ملاحظات الانطلاق (اختياري)"
          />
          <div className="mt-5 grid grid-cols-2 gap-2">
            <button type="button" onClick={onClose} className="h-11 rounded-xl border font-bold">
              إلغاء
            </button>
            <button
              data-testid="confirm-departure"
              disabled={
                !selected || recipients.isLoading || !effectiveManager || departure.isPending || !canDepart.allowed
              }
              title={canDepart.title}
              className="h-11 rounded-xl bg-cyan-700 font-black text-white disabled:opacity-50"
            >
              {departure.isPending
                ? 'جارٍ الإرسال…'
                : mode === 'manual'
                  ? 'تأكيد الانطلاق وإبلاغ المختار'
                  : 'تأكيد الانطلاق والإبلاغ التلقائي'}
            </button>
          </div>
        </div>
      </form>
    </div>
  )
}
function GarageDailyFolders({
  days,
  selected,
  onSelect,
}: {
  days: Array<{ tripDay: string; totalCount: number; openCount: number }>
  selected: string
  onSelect: (day: string) => void
}) {
  const label = (d: string) =>
    new Intl.DateTimeFormat('ar-IQ-u-nu-latn', {
      weekday: 'short',
      day: 'numeric',
      month: 'long',
      year: 'numeric',
      timeZone: 'Asia/Baghdad',
    }).format(new Date(`${d}T12:00:00Z`))
  return (
    <section
      className="rounded-3xl border bg-white p-4 shadow-sm"
      data-testid="garage-trip-day-folders"
    >
      <div className="mb-3 flex items-center gap-2">
        <FolderOpen className="size-5 text-amber-600" />
        <h2 className="font-black">مجلدات حركة الأيام</h2>
        <span className="text-[11px] text-slate-500">فتح يوم واحد يمنع ازدحام السجل</span>
        <input
          aria-label="فتح يوم محدد"
          type="date"
          value={selected}
          onChange={(e) => onSelect(e.target.value)}
          className="mr-auto h-9 rounded-xl border px-2 text-xs"
        />
      </div>
      <div className="flex gap-2 overflow-x-auto pb-2">
        {days.map((d) => (
          <button
            key={d.tripDay}
            data-testid={`garage-trip-day-${d.tripDay}`}
            onClick={() => onSelect(d.tripDay)}
            className={`min-w-44 rounded-2xl border p-3 text-right ${selected === d.tripDay ? 'border-cyan-600 bg-cyan-50 ring-2 ring-cyan-100' : 'bg-slate-50 hover:border-amber-400'}`}
          >
            <b className="block text-xs">{label(d.tripDay)}</b>
            <span className="mt-1 block text-[11px] text-slate-500">
              {d.totalCount} انطلاقة
              {d.openCount > 0 && (
                <em className="mr-2 not-italic font-black text-emerald-700">
                  · {d.openCount} مفتوحة
                </em>
              )}
            </span>
          </button>
        ))}
      </div>
      {!days.length && (
        <p className="py-3 text-center text-xs text-slate-500">سيظهر أول مجلد عند تسجيل انطلاقة.</p>
      )}
    </section>
  )
}
